import math

def primes_upto(n):
    """埃氏筛 + 切片批量标记:用 bytearray 存表,外层只到 √n,内层用
    sieve[i*i::i] = bytes(k) 一次性把整条等差子序列清零,热点交给 C,Python 里最快。"""
    if n < 2:
        return []
    sieve = bytearray([1]) * (n + 1)     # 1=暂定素数,0=合数
    sieve[0] = sieve[1] = 0
    for i in range(2, math.isqrt(n) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytes(len(sieve[i * i :: i]))
    return [i for i in range(2, n + 1) if sieve[i]]

def primes_upto(n):
    """线性筛(欧拉筛):每个合数只被它的最小质因子标记一次,做到 O(n)。
    关键在内层 break —— 当 i % p == 0 时 p 是 i 的最小质因子,继续用更大素数标记会重复。"""
    if n < 2:
        return []
    is_comp = bytearray(n + 1)
    primes = []
    for i in range(2, n + 1):
        if not is_comp[i]:
            primes.append(i)
        for p in primes:
            if i * p > n:
                break
            is_comp[i * p] = 1
            if i % p == 0:               # p 是 i 的最小质因子,保证每个合数只标一次
                break
    return primes
